#!/usr/bin/env python3
"""Source-bound, offline manufacturer sensor integration viewer; no mechanism edits."""
from pathlib import Path
import hashlib,json
import numpy as np
import trimesh
D=Path(__file__).resolve().parent
ROOT=D.parent.parent
BASE=D.parent/'flat132-hand-fit-2026-10-19'
PROXIES={'H01','H01a','H01b','H01c','H01d'}
CLOSE={'P05','H02','H12','H15','H160','H161','H180','H181','H20','H11','H13','H21','H22'}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def js(v):return json.dumps(v,separators=(',',':'),ensure_ascii=False)
def arr(v):return np.round(v,5).tolist()
def trace(mesh,name,color,opacity=1):
    v,f=mesh.vertices,mesh.faces
    return dict(type='mesh3d',name=name,x=arr(v[:,0]),y=arr(v[:,1]),z=arr(v[:,2]),i=f[:,0].tolist(),j=f[:,1].tolist(),k=f[:,2].tolist(),color=color,opacity=opacity,flatshading=False,showlegend=False,text=name,hovertemplate='%{text}<br>X %{x:.2f} · Y %{y:.2f} · Z %{z:.2f} mm<extra></extra>',lighting=dict(ambient=.65,diffuse=.8,specular=.3,roughness=.6,fresnel=.03),lightposition=dict(x=200,y=-100,z=200))
def group(ref):
    if ref in PROXIES:return 'proxy'
    if ref=='H02':return 'pusher'
    if ref=='H12':return 'backing'
    if ref=='P05':return 'cassette'
    if ref in CLOSE:return 'mounts'
    return 'device'
def main():
    prov=json.loads((BASE/'provenance.json').read_text())
    sensor_file=D/'sensor'/'TE_FX1901_actual_apex_aligned_132_mm.stl'
    assert sensor_file.exists(), 'Final apex-aligned STL required'
    audit=json.loads((D/'sensor'/'sensor-geometry-audit.json').read_text())
    assert sha(sensor_file)==audit['output_files'][sensor_file.name]['sha256']
    assert audit['placement']['matrix'][0][3]==-1.9
    sensor=trimesh.load_mesh(sensor_file)
    source=ROOT/'vendor/te_fx1901/c-fx1901-0001-0200-l-f-3d.stp'
    assert source.exists() and sha(source)==audit['source']['sha256']
    prior=(BASE/'viewer.html').read_text()
    prior_data,prior_end=json.JSONDecoder().raw_decode(prior.split('const data=',1)[1])
    prior_meta=json.JSONDecoder().raw_decode(prior.split('const data=',1)[1][prior_end:].split(',meta=',1)[1])[0]
    prior_parts={q['ref']:q for q in prior_meta['parts']}
    data=[trace(sensor,'Actual TE FX1901-0001-0200-L · manufacturer STEP','#de753d')]
    rows=[dict(ref='ACTUAL_SENSOR',name=data[0]['name'],index=0,group='actual',bounds=arr(sensor.bounds),sha256=sha(sensor_file),source=str(sensor_file.relative_to(ROOT)),faces=len(sensor.faces))]
    for p in sorted((BASE/'assembly-mm').glob('*.stl')):
        ref=p.stem;q=prov['parts'][ref]
        assert sha(p)==q['sha256'],ref+' native STL hash differs'
        m=trimesh.load_mesh(p);g=group(ref)
        color={'proxy':'#8863c5','pusher':'#1c5d85','backing':'#72899a','cassette':'#228c93','mounts':'#76838b','device':'#a5b5bf'}[g]
        opacity={'proxy':.25,'pusher':1,'backing':.65,'cassette':.22,'mounts':.6,'device':.65}[g]
        rows.append(dict(ref=ref,name=q['name'],index=len(data),group=g,bounds=arr(m.bounds),sha256=sha(p),source=str(p.relative_to(ROOT)),faces=len(m.faces)))
        if ref in ('H030','H031'):
            assert prior_parts[ref]['sha256']==sha(p)
            display=prior_data[prior_parts[ref]['index']]
            tr={k:v for k,v in display.items()}
            tr.update(color=color,opacity=opacity,name=q['name'])
            rows[-1]['originalFaces']=len(m.faces)
            rows[-1]['faces']=len(tr['i'])
            rows[-1]['displayNote']='Prior source-bound 8,000-face display mesh for indicative spring only; original hash retained.'
            data.append(tr)
        else:data.append(trace(m,q['name']+(' · OLD SIMPLIFIED PROXY' if g=='proxy' else ''),color,opacity))
    assert len(rows)==52
    for p in sorted((D/'sensor').glob('conflict-*.stl')):
        m=trimesh.load_mesh(p)
        rows.append(dict(ref=p.stem,name=p.stem+' · exact nominal solid intersection',index=len(data),group='conflict',bounds=arr(m.bounds),sha256=sha(p),source=str(p.relative_to(ROOT)),faces=len(m.faces)))
        data.append(trace(m,rows[-1]['name'],'#ef3251',1))
    handfile=BASE/'hand-mm.ply'
    if handfile.exists():
        assert sha(handfile)==prov['registered_hand_ply_sha256']
        hand=trimesh.load_mesh(handfile,process=False);tr=trace(hand,'Original registered hand scan · provisional pose','#e2b49c')
        colors=np.asarray(hand.visual.vertex_colors)
        if len(colors)==len(hand.vertices):tr['vertexcolor']=[f'rgb({r},{g},{b})' for r,g,b in colors[:,:3]]
        rows.append(dict(ref='HAND',name=tr['name'],index=len(data),group='hand',bounds=arr(hand.bounds),sha256=sha(handfile),source=str(handfile.relative_to(ROOT)),faces=len(hand.faces)))
        data.append(tr)
    actual_bounds=arr(sensor.bounds)
    meta=dict(rows=rows,stepSha256=sha(source),sensorStlSha256=sha(sensor_file),sensorBounds=actual_bounds,nativeSourceSha256=prov['cad_sha256'],exportSha256=prov['export_sha256'],stepPath=str(source.relative_to(ROOT)),branch=prov['branch'],actualBranch='https://cad.onshape.com/documents/15316cc6370631845af136b2/w/3ee26cf6386f889ca7ae9519/e/d253eb87b70818ebde8215f0',configuration=prov['configuration'],auditComparisons=audit['comparisons'],placement={'R':[[0,0,1],[1,0,0],[0,1,0]],'t_mm':[-1.9,0,18],'constraint':'Central spherical button apex at X -1.9 mm, aligned to unchanged H02 tip. Flat disk is recessed 0.51 mm behind apex. Lead toward +Y. No sensor rescale.'})
    plotlyjs=prior.split('<script>',1)[1].split('</script>',1)[0]
    assert 'plotly' in plotlyjs.lower() and len(plotlyjs)>1000000
    html=TEMPLATE.replace('__PLOTLY__',plotlyjs).replace('__DATA__',js(data)).replace('__META__',js(meta))
    out=D/'viewer.html';out.write_text(html)
    report=dict(viewer='viewer.html',sha256=sha(out),bytes=out.stat().st_size,offline=True,source_step_sha256=sha(source),actual_sensor_stl_sha256=sha(sensor_file),native_assembly_count=51,actual_sensor_onshape_branch=meta['actualBranch'],previous_proxy_baseline_branch=meta['branch'],display='Full actual manufacturer sensor and mount tessellations, unchanged coordinates. Two indicative springs reuse prior source-bound 8,000-face display meshes; original STL hashes retained.',baseline_files_modified=False,proxies_hidden_by_default=sorted(PROXIES),hand_hidden_by_default=True,parts=rows,placement=meta['placement'])
    (D/'viewer-build.json').write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps({k:v for k,v in report.items() if k!='parts'},indent=2))
